/* Halloween 2026 — approved complete cinematic poster, no distorted characters. */
(function(){
'use strict';
function parisClock(){
 var result={};
 var parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date());
 parts.forEach(function(p){result[p.type]=p.value;});
 return Number(result.year+result.month+result.day+result.hour+result.minute);
}
var from=202610280000,until=202611030000;
if(parisClock()<from||parisClock()>=until)return;
document.documentElement.classList.add('mma-halloween-final');
var style=document.createElement('link');style.rel='stylesheet';style.href='css/halloween2026-final.css?v=20261028b';document.head.appendChild(style);
function start(){
 var home=document.getElementById('accueil');
 if(!home)return;
 var oldHero=home.querySelector('.home-hero');
 if(!oldHero)return;
 var poster=document.createElement('div');poster.className='mma-halloween-film';poster.setAttribute('aria-label','Halloween au club Mix Martial Academy, reprise des cours lundi 2 novembre 2026');
 var picture=document.createElement('img');picture.alt='Décor Halloween cinématographique Mix Martial Academy avec Ghostface, Dracula, Chucky, lune rouge et citrouilles. Reprise des cours lundi 2 novembre 2026.';picture.src="data:image/webp;base64,";picture.width=768;picture.height=731;picture.decoding='async';picture.fetchPriority='high';
 poster.appendChild(picture);
 var fog=document.createElement('span');fog.className='mma-halloween-fog';fog.setAttribute('aria-hidden','true');poster.appendChild(fog);
 home.insertBefore(poster,oldHero);
 function remove(){
  document.documentElement.classList.remove('mma-halloween-final');
  if(poster.parentNode)poster.remove();
  if(style.parentNode)style.remove();
 }
 var watcher=setInterval(function(){if(parisClock()>=until){clearInterval(watcher);remove();}},15000);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
}());